/**
 * D12 Runtime Q&A: a fictional programming Q&A site about Python and data tools, generated by Runtime in the shape of
 * a Stack Exchange data dump: users, questions and answers with HTML bodies, tags written "<python><pandas>",
 * scores, views and accepted answers, plus the posts as a dump-style Posts.xml.
 *
 * Generated instead of acquired: Stack Exchange content is CC BY-SA with per-post attribution, and current dump terms
 * restrict reuse, so this course doesn't redistribute it. Every user, question and answer here is invented.
 * Text problems are kept: HTML in bodies, code blocks, entities (&lt; &amp;), tags in one string, deleted owners.
 */
import { createRng, hash32, ts, ms, DAY, HOUR } from '../../lib/rng.mjs';

const SEED = 20261212;
const col = (name, type, description, nullable = false) => ({ name, type, description, nullable });
const START = ms('2023-01-01');
const END = ms('2025-06-30 23:59:59');

/** Topics: tags, and the things a question can be about. */
const TOPICS = [
  { tags: ['python', 'pandas'], w: 18, verbs: ['merge two DataFrames on', 'group by and sum', 'drop rows where', 'convert a column to datetime for', 'pivot', 'fill missing values in', 'read a CSV with'], objs: ['a date column', 'multiple columns', 'an index', 'string values', 'a MultiIndex', 'NaN values'], errs: ['KeyError', 'SettingWithCopyWarning', 'ValueError: cannot reindex on an axis with duplicate labels', 'TypeError: unhashable type: \'list\''], code: ['df = pd.read_csv("sales.csv")\ndf.groupby("region")["amount"].sum()', 'merged = left.merge(right, on="id", how="left")', 'df["date"] = pd.to_datetime(df["date"], format="%Y-%m-%d")', 'df.loc[df["qty"] < 0, "qty"] = 0'] },
  { tags: ['python', 'list'], w: 10, verbs: ['remove duplicates from', 'flatten', 'sort', 'split', 'find the index of'], objs: ['a list of dicts', 'nested lists', 'a list of tuples', 'a list while iterating'], errs: ['IndexError: list index out of range', 'TypeError: \'<\' not supported between instances of \'str\' and \'int\''], code: ['items = [3, 1, 2]\nitems.sort(reverse=True)', 'flat = [x for row in grid for x in row]', 'unique = list(dict.fromkeys(names))'] },
  { tags: ['python', 'dictionary'], w: 8, verbs: ['merge', 'invert', 'sort by value', 'iterate over', 'get a default from'], objs: ['a dictionary', 'nested dictionaries', 'a dict of lists'], errs: ['KeyError', 'RuntimeError: dictionary changed size during iteration'], code: ['merged = {**a, **b}', 'counts = {}\nfor w in words:\n    counts[w] = counts.get(w, 0) + 1'] },
  { tags: ['python', 'numpy'], w: 8, verbs: ['vectorize', 'reshape', 'broadcast', 'index'], objs: ['a 2D array', 'a boolean mask', 'an array of strings'], errs: ['ValueError: operands could not be broadcast together', 'IndexError: too many indices for array'], code: ['a = np.arange(12).reshape(3, 4)\na[a > 5]', 'np.where(arr > 0, arr, 0)'] },
  { tags: ['python', 'sqlite'], w: 6, verbs: ['insert many rows into', 'query', 'commit changes to', 'use parameters with'], objs: ['a SQLite database', 'a table', 'a transaction'], errs: ['sqlite3.OperationalError: database is locked', 'sqlite3.IntegrityError: UNIQUE constraint failed', 'sqlite3.ProgrammingError: Incorrect number of bindings supplied'], code: ['conn.execute("INSERT INTO t VALUES (?, ?)", (1, "a"))\nconn.commit()', 'cur.executemany("INSERT INTO items VALUES (?, ?)", rows)'] },
  { tags: ['python', 'datetime'], w: 6, verbs: ['parse', 'convert time zones for', 'subtract', 'format'], objs: ['an ISO timestamp', 'a naive datetime', 'a Unix timestamp'], errs: ['TypeError: can\'t compare offset-naive and offset-aware datetimes', 'ValueError: time data does not match format'], code: ['datetime.strptime(s, "%Y-%m-%d %H:%M")', 'dt.astimezone(ZoneInfo("America/New_York"))'] },
  { tags: ['python', 'regex'], w: 5, verbs: ['match', 'extract', 'replace', 'split on'], objs: ['an email address', 'digits in a string', 'repeated whitespace'], errs: ['re.error: unterminated character set'], code: ['re.findall(r"\\d+", text)', 're.sub(r"\\s+", " ", s).strip()'] },
  { tags: ['python', 'json'], w: 5, verbs: ['parse', 'serialize', 'read', 'flatten'], objs: ['a nested JSON response', 'a JSON Lines file', 'a datetime to JSON'], errs: ['json.decoder.JSONDecodeError: Expecting value', 'TypeError: Object of type datetime is not JSON serializable'], code: ['data = json.loads(text)\nfor item in data["results"]:\n    print(item["id"])', 'with open("events.jsonl") as f:\n    rows = [json.loads(line) for line in f]'] },
  { tags: ['python', 'asyncio'], w: 4, verbs: ['run', 'cancel', 'gather', 'limit concurrency of'], objs: ['async tasks', 'a coroutine', 'HTTP requests'], errs: ['RuntimeError: This event loop is already running', 'RuntimeWarning: coroutine was never awaited'], code: ['results = await asyncio.gather(*tasks)', 'async with sem:\n    return await fetch(url)'] },
  { tags: ['python', 'performance'], w: 4, verbs: ['speed up', 'profile', 'reduce memory of'], objs: ['a nested loop', 'a large CSV read', 'string concatenation'], errs: ['MemoryError'], code: ['for i in range(len(a)):\n    for j in range(len(b)):\n        if a[i] == b[j]:\n            hits += 1', 'total = "".join(parts)'] },
  { tags: ['python', 'matplotlib'], w: 4, verbs: ['label', 'resize', 'plot', 'save'], objs: ['a bar chart', 'two y axes', 'a histogram'], errs: ['ValueError: x and y must have same first dimension'], code: ['plt.bar(names, values)\nplt.xticks(rotation=45)\nplt.tight_layout()'] },
  { tags: ['python', 'class'], w: 5, verbs: ['define', 'inherit from', 'compare instances of', 'copy'], objs: ['a dataclass', 'a base class', 'a class attribute'], errs: ['TypeError: __init__() missing 1 required positional argument', 'AttributeError: object has no attribute'], code: ['@dataclass\nclass Point:\n    x: float\n    y: float', 'class Dog(Animal):\n    def speak(self):\n        return "woof"'] },
  { tags: ['python', 'duckdb'], w: 2, verbs: ['query', 'join', 'read'], objs: ['a Parquet file', 'a pandas DataFrame with SQL'], errs: ['duckdb.CatalogException: Table does not exist'], code: ['duckdb.sql("SELECT region, sum(amount) FROM df GROUP BY region")'] },
  { tags: ['python', 'polars'], w: 2, verbs: ['filter', 'group by', 'convert'], objs: ['a Polars DataFrame', 'a lazy frame'], errs: ['ColumnNotFoundError'], code: ['df.filter(pl.col("qty") > 0).group_by("sku").agg(pl.col("qty").sum())'] },
];
const EXTRA_TAGS = ['python-3.x', 'csv', 'string', 'loops', 'function', 'exception', 'unicode', 'sorting', 'file', 'list-comprehension', 'generator', 'typing', 'testing', 'pytest'];
const OPENERS = ['I am trying to', 'How can I', 'What is the best way to', 'Is there a way to', 'I want to', 'Beginner here: how do I'];
const AFTER = ['but it is very slow.', 'and I get an error.', 'without a loop?', 'in one line?', 'but the result is empty.', 'and keep the original order.', ''];
const PLACES = ['Berlin', 'India', 'San Francisco, CA', 'London, United Kingdom', 'Bangalore', 'NYC', 'Toronto, Canada', 'Earth', '', 'Lagos, Nigeria', 'São Paulo', 'Tokyo', 'Paris, France', 'Seattle, WA', 'Remote'];
const NAMES = ['coder', 'dev', 'py', 'data', 'learner', 'hacker', 'analyst', 'eng', 'student', 'ninja'];

const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function generate() {
  const rng = createRng(SEED);
  const uRng = rng.fork('users');
  const users = [];
  for (let i = 1; i <= 5200; i++) {
    const created = ms('2012-01-01') + Math.floor(uRng.next() ** 0.6 * (END - ms('2012-01-01') - 30 * DAY));
    users.push({
      user_id: i * 13 + 7, display_name: uRng.chance(0.25) ? `user${uRng.int(100000, 9999999)}` : `${uRng.pick(NAMES)}${uRng.pick(['_', '', '.'])}${uRng.pick(['sam', 'kai', 'li', 'ana', 'raj', 'max', 'eve', 'tom', 'mo', 'zed'])}${uRng.chance(0.5) ? uRng.int(1, 99) : ''}`,
      reputation: Math.max(1, Math.round(uRng.lognormal(60, 2.1))), created_at: ts(created), location: uRng.chance(0.55) ? uRng.pick(PLACES) || null : null,
      _skill: uRng.lognormal(1, 1.2), _created: created,
    });
  }
  const answerers = users.slice().sort((a, b) => b._skill - a._skill);
  const qRng = rng.fork('questions');
  const questions = [], answers = [];
  let qid = 70_000_000, aid = 70_000_001;
  const span = END - START;
  for (let i = 0; i < 9000; i++) {
    const topic = qRng.weighted(TOPICS.map(t => [t, t.w]));
    const t = START + Math.floor((i / 9000) * span) + qRng.int(0, 3 * HOUR / 1000) * 1000;
    const owner = users[qRng.int(0, users.length - 1)];
    const isError = qRng.chance(0.3);
    const err = qRng.pick(topic.errs);
    const verb = qRng.pick(topic.verbs), obj = qRng.pick(topic.objs);
    const title = isError ? `${err.split(':')[0]} when I ${verb} ${obj}` : qRng.chance(0.5) ? `How to ${verb} ${obj} in ${topic.tags[1] === 'list' || topic.tags[1] === 'dictionary' || topic.tags[1] === 'class' ? 'Python' : topic.tags[1]}?` : `${qRng.pick(OPENERS)} ${verb} ${obj} ${qRng.pick(AFTER)}`.trim();
    const code = qRng.pick(topic.code);
    const body = `<p>${esc(`${qRng.pick(OPENERS)} ${verb} ${obj} ${qRng.pick(AFTER)}`.trim())}</p>\n<pre><code>${esc(code)}\n</code></pre>\n` +
      (isError ? `<p>I get this error:</p>\n<pre><code>${esc(err)}\n</code></pre>\n` : '') + `<p>${esc(qRng.pick(['What am I doing wrong?', 'Any ideas?', 'Thanks in advance!', 'I am using Python 3.12.', 'Is there a more pythonic way?', 'I already tried searching for this.']))}</p>`;
    const tags = [...new Set([...topic.tags, ...(qRng.chance(0.4) ? [qRng.pick(EXTRA_TAGS)] : [])])];
    const quality = qRng.normal(0, 1);
    const views = Math.round(qRng.lognormal(140, 1.5) * (1 + ((END - t) / span) * 2));
    const nAns = qRng.chance(0.18) ? 0 : Math.min(8, qRng.poisson(1.4 + Math.max(0, quality)));
    const question = {
      question_id: qid, owner_user_id: qRng.chance(0.03) ? null : owner.user_id, title, body, tags: tags.map(x => `<${x}>`).join(''),
      score: Math.round(Math.max(-6, quality * 2 + Math.log10(views + 1) - 1.5 + qRng.normal(0, 1))), view_count: views, answer_count: nAns,
      accepted_answer_id: null, created_at: ts(t), closed_at: null, closed_reason: null, last_activity_at: ts(t),
    };
    if (qRng.chance(0.06)) { question.closed_at = ts(t + qRng.int(1, 48) * HOUR); question.closed_reason = qRng.pick(['Duplicate', 'Needs details or clarity', 'Needs more focus', 'Not reproducible or caused by a typo']); }
    let last = t;
    const mine = [];
    for (let k = 0; k < nAns; k++) {
      const by = answerers[Math.floor(qRng.next() ** 2.5 * answerers.length)];
      const at = t + Math.round(qRng.exponential(k === 0 ? 3 : 30) * HOUR);
      if (at > END) continue;
      const good = qRng.normal(Math.log(by._skill + 1), 1);
      const fixCode = qRng.pick(topic.code);
      const ab = `<p>${esc(qRng.pick(['You can use', 'Try', 'The simplest way is', 'Use', 'This happens because']))} ${qRng.pick([`<code>${esc(topic.tags[1])}</code>`, 'a list comprehension', 'the built-in function', 'vectorized operations', 'a context manager'])}:</p>\n<pre><code>${esc(fixCode)}\n</code></pre>\n<p>${esc(qRng.pick(['This avoids the loop entirely.', 'See the docs for details.', 'Note that this returns a new object.', 'It is O(n) instead of O(n²).', 'Works on Python 3.8+.', 'Hope this helps!']))}</p>`;
      const a = { answer_id: aid, question_id: qid, owner_user_id: qRng.chance(0.03) ? null : by.user_id, body: ab, score: Math.round(Math.max(-3, good * 2 + qRng.normal(0, 1.5))), created_at: ts(at), is_accepted: 0 };
      aid += 3;
      mine.push(a);
      last = Math.max(last, at);
    }
    if (mine.length && question.owner_user_id !== null && qRng.chance(0.62)) {
      const best = mine.slice().sort((x, y) => y.score - x.score)[qRng.chance(0.8) ? 0 : mine.length - 1];
      best.is_accepted = 1;
      question.accepted_answer_id = best.answer_id;
    }
    question.answer_count = mine.length;
    question.last_activity_at = ts(last);
    answers.push(...mine);
    questions.push(question);
    qid += 7;
  }
  const strip = o => Object.fromEntries(Object.entries(o).filter(([k]) => !k.startsWith('_')));
  return { users: users.map(strip), questions, answers };
}

const EDITIONS = { preview: { questions: 12 }, starter: { questions: 300 }, standard: { questions: 2500 }, full: { questions: Infinity } };

function cutEdition(full, edition) {
  const n = EDITIONS[edition].questions;
  const questions = n === Infinity ? full.questions : full.questions.slice().sort((a, b) => hash32(`${edition}|${a.question_id}`) - hash32(`${edition}|${b.question_id}`)).slice(0, n).sort((a, b) => a.question_id - b.question_id);
  const ids = new Set(questions.map(q => q.question_id));
  const answers = full.answers.filter(a => ids.has(a.question_id));
  const people = new Set([...questions, ...answers].map(p => p.owner_user_id).filter(x => x !== null));
  return { users: full.users.filter(u => people.has(u.user_id)), questions, answers };
}

/** The posts as a Stack Exchange-style dump: one <row/> per post, attributes only, HTML escaped inside. */
function postsXml({ questions, answers }) {
  const rows = [
    ...questions.map(q => ({ Id: q.question_id, PostTypeId: 1, AcceptedAnswerId: q.accepted_answer_id, CreationDate: q.created_at.replace(' ', 'T') + '.000', Score: q.score, ViewCount: q.view_count, Body: q.body, OwnerUserId: q.owner_user_id, LastActivityDate: q.last_activity_at.replace(' ', 'T') + '.000', Title: q.title, Tags: q.tags, AnswerCount: q.answer_count, ClosedDate: q.closed_at ? q.closed_at.replace(' ', 'T') + '.000' : null })),
    ...answers.map(a => ({ Id: a.answer_id, PostTypeId: 2, ParentId: a.question_id, CreationDate: a.created_at.replace(' ', 'T') + '.000', Score: a.score, Body: a.body, OwnerUserId: a.owner_user_id })),
  ].sort((a, b) => a.Id - b.Id);
  const attr = r => Object.entries(r).filter(([, v]) => v !== null && v !== undefined).map(([k, v]) => `${k}="${esc(String(v)).replace(/\n/g, '&#xA;')}"`).join(' ');
  return `<?xml version="1.0" encoding="utf-8"?>\n<posts>\n${rows.map(r => `  <row ${attr(r)} />`).join('\n')}\n</posts>\n`;
}

function extraFiles(tables, edition) {
  if (edition === 'full') return [];
  return [{ path: 'Posts.xml', table: 'questions', text: postsXml(tables), rows: tables.questions.length + tables.answers.length }];
}

function realIssues({ questions, answers }) {
  return [
    { id: 'html_bodies', description: 'Bodies are HTML with escaped code (&lt;, &gt;, &amp;)', count: questions.length + answers.length },
    { id: 'tags_one_string', description: 'All of a question’s tags in one string: "<python><pandas>"', count: questions.length },
    { id: 'deleted_owners', description: 'Posts whose owner account was deleted (owner_user_id empty)', count: [...questions, ...answers].filter(p => p.owner_user_id === null).length },
    { id: 'unanswered', description: 'Questions with no answers', count: questions.filter(q => q.answer_count === 0).length },
    { id: 'closed', description: 'Closed questions', count: questions.filter(q => q.closed_at).length },
  ];
}

const dataset = {
  id: 'D12',
  title: 'Runtime Q&A',
  version: 1,
  seed: SEED,
  description:
    'A fictional programming Q&A site about Python and data tools, 2023–2025: users, questions and answers with ' +
    'HTML bodies and code, tags, scores, views and accepted answers, in the shape of a Stack Exchange data dump. ' +
    'Generated by Runtime; every user and post is invented.',
  licence: { name: 'Runtime-owned synthetic data', status: 'ours' },
  generator: 'datasets/python/D12/dataset.mjs',
  window: ['2023-01-01', '2025-06-30'],
  tables: {
    users: {
      description: 'One user who asked or answered a question here.',
      primaryKey: ['user_id'],
      columns: [col('user_id', 'integer', 'User ID'), col('display_name', 'text', 'Invented display name'), col('reputation', 'integer', 'Reputation points'), col('created_at', 'timestamp', 'Account created, UTC'), col('location', 'text', 'Free-text location', true)],
    },
    questions: {
      description: 'One question.',
      primaryKey: ['question_id'],
      foreignKeys: [{ column: 'owner_user_id', references: 'users.user_id' }],
      columns: [
        col('question_id', 'integer', 'Question ID'), col('owner_user_id', 'integer', 'Who asked; empty if the account was deleted', true), col('title', 'text', 'Title'),
        col('body', 'text', 'HTML body'), col('tags', 'text', 'Tags as "<python><pandas>"'), col('score', 'integer', 'Up votes minus down votes'),
        col('view_count', 'integer', 'Views'), col('answer_count', 'integer', 'Answers'), col('accepted_answer_id', 'integer', 'The accepted answer, if any', true),
        col('created_at', 'timestamp', 'Asked, UTC'), col('closed_at', 'timestamp', 'Closed, UTC', true), col('closed_reason', 'text', 'Why it was closed', true),
        col('last_activity_at', 'timestamp', 'Last activity, UTC'),
      ],
    },
    answers: {
      description: 'One answer to a question.',
      primaryKey: ['answer_id'],
      foreignKeys: [{ column: 'question_id', references: 'questions.question_id' }, { column: 'owner_user_id', references: 'users.user_id' }],
      columns: [col('answer_id', 'integer', 'Answer ID'), col('question_id', 'integer', 'Question'), col('owner_user_id', 'integer', 'Who answered; empty if deleted', true), col('body', 'text', 'HTML body'), col('score', 'integer', 'Score'), col('created_at', 'timestamp', 'Answered, UTC'), col('is_accepted', 'integer', '1 for the accepted answer')],
    },
  },
  editions: Object.fromEntries(Object.keys(EDITIONS).map(k => [k, k])),
  stress: false,
  generate,
  cutEdition,
  extraFiles,
  realIssues,
};

export default dataset;
